  "stuSess.penaltyChoiceRefundDesc": "Visszatérítésért (€{amount}) írj az info@tutlio.lt címre. Ha kártyával fizettél, a visszatérítés ettől függetlenül automatikusan is elindulhat a Stripe-on keresztül.",
