  "stuSess.creditAppliedSuccess": "€{amount} jóváírást adtunk az egyenlegedhez, amelyet automatikusan beszámítunk a következő órád árába.",
  "stuSess.refundContactNote": "Visszatérítésért írj az <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a> címre.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Kérdésed vagy problémád van? Írj az <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a> címre.</p><p class=\"font-semibold text-emerald-900\">A visszatérítést elindítottuk a Stripe-on keresztül.</p><p class=\"text-emerald-800 mt-1\">A kártyás visszatérítés általában <strong>5–10 munkanapon belül</strong> érkezik meg (bankonként eltérhet). Ha a szokásos időn belül nem kapod meg, írj az <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a> címre.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Úgy tűnik, ezt az órát nem a Tutlio Stripe-rendszerén keresztül fizetted ki (hanem például banki átutalással vagy készpénzzel). Itt nincs automatikus visszatérítés.</p><p class=\"mt-2\">A visszatérítés egyeztetéséhez keresd a magántanárodat: <strong>{tutor}</strong>. Az elérhetőségét megtalálod a foglalásaidnál, vagy közvetlenül tőle kérheted el.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Úgy tűnik, ezt az órát nem a Tutlio Stripe-rendszerén keresztül fizetted ki (hanem például banki átutalással vagy készpénzzel). Itt nincs automatikus visszatérítés.</p><p class=\"mt-2\">Mivel szervezeten keresztül tanulsz, a <strong>szervezet adminisztrátorához</strong> fordulj (a magántanárodon keresztül vagy a szervezet nyilvános elérhetőségein).</p>",
