  "landing.footerResources": "Tudástár",
  "landing.footerCompany": "Vállalkozás",
  "landing.faq.whatIsQ": "Mi a Tutlio?",
  "landing.faq.whatIsA": "A Tutlio oktatásszervezési platform, amellyel az egyéni magántanárok és oktatási központok egy helyen kezelhetik az órarendet, a fizetéseket, a diákokkal való kapcsolattartást és az órák nyilvántartását.",
  "landing.faq.whoForQ": "Kinek szól a Tutlio?",
  "landing.faq.whoForA": "A Tutlio magántanároknak, zenetanároknak, nyelvtanároknak, matematikatanároknak, valamint bármilyen méretű oktatási iskoláknak és központoknak készült.",
  "landing.faq.waitlistQ": "Hogyan működik a diákvárólista?",
  "landing.faq.waitlistA": "Ha egy diák lemond egy órát, a felszabadult időpontot automatikusan felajánljuk a várólistán lévő diákoknak. Aki először megerősíti, az kapja a helyet – így a magántanár nem veszít bevételt a lemondás miatt.",
  "landing.faq.freeTrialQ": "Van ingyenes próbaidőszak?",
  "landing.faq.freeTrialA": "Igen! Minden új fiók automatikusan 7 ingyenes napot kap – nincs szükség kódra. A próbaidőszak alatt nincs terhelés, és bármikor lemondhatod.",
  "landing.faq.languagesQ": "Milyen nyelveken érhető el a Tutlio?",
  "landing.faq.languagesA": "A Tutlio {count} nyelven érhető el: {languages}.",
  "landing.faqTitle": "Gyakori kérdések",
  "landing.feature.digital-business-card": "Digitális névjegy",
  "landing.feature.digital-business-cardDesc": "Ossz meg egy professzionális oldalt, ahol a diákok megismerhetnek, láthatják az aktuális árakat és szabad időpontokat, és rögtön órát kérhetnek.",
  "featuresIndex.newBadge": "Új",
  "feature.digital-business-card.pageTitle": "Digitális névjegy, amely az érdeklődést órakéréssé alakítja",
  "feature.digital-business-card.pageDesc": "Adj minden leendő diáknak egy igényes linket a bemutatkozásoddal, óráiddal, áraiddal, értékeléseiddel és aktuális szabad időpontjaiddal. Rögtön választhatnak órát és időpontot – az érdeklődések nem vesznek el hosszú üzenetváltásokban.",
  "feature.digital-business-card.detailsTitle": "Minden, amire egy leendő diáknak szüksége van a döntéshez",
  "feature.digital-business-card.oneLink": "Egy link az egész oktatási vállalkozásodhoz",
  "feature.digital-business-card.oneLinkDesc": "Váltsd ki a szétszórt közösségi profilokat, árlistákat és foglalási üzeneteket egy bárhol megosztható oldallal.",
  "feature.digital-business-card.liveAvailability": "Mindig naprakész szabad időpontok",
  "feature.digital-business-card.liveAvailabilityDesc": "A szabad időpontok közvetlenül a Tutlio-naptáradból érkeznek, így az ügyfelek csak olyan időpontot kérhetnek, amikor valóban tanítani szeretnél.",
  "feature.digital-business-card.instantEnquiries": "Órakérések akkor is, amikor tanítasz",
  "feature.digital-business-card.instantEnquiriesDesc": "A szülő vagy a diák kiválasztja az órát, a formát és az időpontot, majd megadja az adatait. A teljes kérés időpontegyeztetés nélkül jut el hozzád.",
  "feature.digital-business-card.professionalBrand": "Professzionális első benyomás",
  "feature.digital-business-card.professionalBrandDesc": "Mutasd be a fényképedet, tanítási módszeredet, tantárgyaidat, áraidat, ellenőrzött értékeléseidet és márkaszíneidet egy olyan oldalon, amely minden telefonon jól mutat.",
  "feature.digital-business-card.faq.whatShowsQ": "Mit jeleníthetek meg a digitális névjegyemen?",
  "feature.digital-business-card.faq.whatShowsA": "Megjelenítheted a bemutatkozásodat, tantárgyaidat, óraformáidat, nyilvános áraidat, szabad időpontjaidat, helyszínedet, nyelveidet, közösségi linkjeidet és ellenőrzött diákértékeléseidet.",
  "feature.digital-business-card.faq.howBookingWorksQ": "Az ügyfél rögtön megerősített órát foglal?",
  "feature.digital-business-card.faq.howBookingWorksA": "Az ügyfél kiválaszt egy órát és egy szabad időpontot, majd elküldi a teljes foglalási kérést. Ezt a Tutlióban kapod meg, ahol jóváhagyhatod az új diákot, mielőtt az óra bekerül az órarendedbe.",
  "feature.digital-business-card.faq.whereShareQ": "Hol osszam meg az oldalt?",
  "feature.digital-business-card.faq.whereShareA": "Használd az Instagramon, a TikTokon, Facebook-csoportokban, hirdetésekben, e-mail-aláírásokban, üzenetekben és QR-kódokban. Ugyanaz a link akkor is naprakész marad, ha változnak az áraid vagy a naptárad.",
  "feature.digital-business-card.demo.eyebrow": "Interaktív ügyfél-előnézet",
  "feature.digital-business-card.demo.title": "Próbáld ki a foglalást",
  "feature.digital-business-card.demo.desc": "Válassz lent órát és időpontot. Az új ügyfelek ezt az egyszerű folyamatot járják végig a megosztott linkedről.",
  "feature.digital-business-card.demo.profile": "Matematikatanár · 9–12. évfolyam",
  "feature.digital-business-card.demo.available": "Új diákokat fogad",
  "feature.digital-business-card.demo.pickLesson": "1. Válassz órát",
  "feature.digital-business-card.demo.individual": "Egyéni óra",
  "feature.digital-business-card.demo.individualDesc": "60 perc · személyes tanulási terv",
  "feature.digital-business-card.demo.exam": "Intenzív vizsgafelkészítés",
