  "enterpriseCheckout.continueToPayment": "Tovább a fizetéshez",
  "pwa.bannerText": "Add a Tutliót a kezdőképernyődhöz, és használd alkalmazásként!",
  "pwa.promptTitle": "Használd a Tutliót alkalmazásként",
  "pwa.promptSubtitle": "Hozzáadás a kezdőképernyőhöz",
  "pwa.promptDescription": "Telepítsd a Tutliót a telefonodra a gyorsabb, alkalmazásszerű használathoz – alkalmazásbolt sem kell hozzá!",
  "pwa.howToInstall": "Hogyan telepíthetem?",
  "pwa.later": "Később",
  "pwa.dontShowAgain": "Ne jelenjen meg újra",
  "pwa.guideTitle": "Telepítés mobilalkalmazásként",
  "pwa.guideSubtitle": "Használd a Tutliót hagyományos alkalmazásként a telefonodon",
  "pwa.guideIntro": "A Tutliót hozzáadhatod a telefonod kezdőképernyőjéhez, és hagyományos alkalmazásként használhatod – teljes képernyőn, gyors hozzáféréssel.",
  "pwa.iosStep1": "Nyisd meg a Tutliót a Safariban, és koppints a képernyő alján a Megosztás gombra (négyzet felfelé mutató nyíllal).",
  "pwa.iosStep2": "Görgess le, és koppints a „Főképernyőhöz adás” lehetőségre.",
  "pwa.iosStep3": "Koppints a „Hozzáadás” gombra – a Tutlio ikonja megjelenik a főképernyődön.",
  "pwa.androidStep1": "Nyisd meg a Tutliót a Chrome-ban, és koppints a jobb felső sarokban a hárompontos menüre (⋮).",
  "pwa.androidStep2": "Koppints a „Hozzáadás a kezdőképernyőhöz” vagy az „Alkalmazás telepítése” lehetőségre.",
  "pwa.androidStep3": "Erősítsd meg – a Tutlio ikonja megjelenik a kezdőképernyődön.",
  "pwa.guideTip": "Telepítés után a legjobb élményért a kezdőképernyőről nyisd meg a Tutliót. Úgy működik, mint egy hagyományos alkalmazás!",
