  "enterprise.message": "Üzenet",
  "enterprise.submit": "Érdeklődés küldése",
  "enterprise.successTitle": "Köszönjük!",
  "enterprise.successDesc": "Megkaptuk az érdeklődésedet, és 1-2 munkanapon belül válaszolunk.",
  "enterpriseSuccess.title": "Fizetés beérkezett!",
  "enterpriseSuccess.orgDesc": "A licencvásárlást megerősítettük, a licenceket hozzáadjuk a szervezetedhez.",
  "enterpriseSuccess.goToCompany": "Tovább a szervezeti irányítópultra",
  "enterpriseSuccess.newDesc": "Köszönjük a vásárlást! Éppen beállítjuk a szervezetedet.",
  "enterpriseSuccess.checkEmail": "Nézd meg az e-mailjeidet – elküldtük az adminisztrátori jelszó beállításához és a szervezeti irányítópult eléréséhez szükséges linket. A levél megérkezése eltarthat egy percig.",
  "enterpriseSuccess.backHome": "Vissza a főoldalra",
  "landing.leadSuccess": "Köszönjük! Hamarosan jelentkezünk.",
  "orgTutorPolicy.title": "Belső szabályzat magántanároknak",
  "orgTutorPolicy.intro": "A platform használata előtt tekintsd át a szervezet belső szabályzatát.",
  "orgTutorPolicy.acceptBtn": "Tudomásul vettem",
  "orgTutorPolicy.viewBtn": "Belső szabályzat megtekintése",
  "orgTutorPolicy.s1Title": "1. Általános rendelkezések",
  "orgTutorPolicy.s1Body": "Ez a szabályzat a Tutlio platform (a továbbiakban: Platform) tanárként vagy magántanárként (a továbbiakban: Magántanár) történő használatát szabályozza. A Platform használatára az általad képviselt oktatási ügynökség, iskola vagy oktatási központ (a továbbiakban: Szervezet) hívott meg. A Platform műszaki üzemeltetését és támogatását az MB Tutlio biztosítja. Fiókod használatával elfogadod ezt a szabályzatot és az adatvédelmi tájékoztatót.",
  "orgTutorPolicy.s2Title": "2. Fiókkezelés és órarendek",
  "orgTutorPolicy.s2Intro": "A Platform célja, hogy ne kelljen időt töltened az óraidőpontok diákokkal történő egyeztetésével.",
  "orgTutorPolicy.s2Link": "Egyedi link: személyes órafoglalási linket kapsz az általad tanított tantárgyak alapján, amelyen a diákok órát foglalhatnak.",
  "orgTutorPolicy.s2Calendar": "Naptárszinkronizálás: a szabad időpontjaid közvetlenül a Google Calendar integrációjától (2 irányú szinkronizálás) függenek. Személyesen felelsz azért, hogy a naptáradban látható szabad időpontok pontosak és naprakészek legyenek. A Platform nem engedi, hogy a diákok a naptáradban foglaltnak jelölt időpontokra foglaljanak.",
  "orgTutorPolicy.s2Security": "Fiókbiztonság: a fiókod személyes. Köteles vagy biztonságban tartani a belépési adataidat, és nem oszthatod meg őket harmadik felekkel.",
  "orgTutorPolicy.s3Title": "3. Óralemondások és várólista",
  "orgTutorPolicy.s3Intro": "A Platform segít kihasználni az órarendedet és elkerülni az üres időpontokat:",
  "orgTutorPolicy.s3Auto": "Ha egy diák lemond egy órát, a Platform automatikusan értesítést (SMS/e-mail) küld a várólistádon szereplő többi diáknak, felajánlva a felszabadult időpontot. Ezzel kapcsolatban nincs további teendőd.",
  "orgTutorPolicy.s3Rules": "Az órák lemondási szabályait (mennyivel előre mondható le az óra, milyen következményekkel) a Szervezeted határozza meg.",
  "orgTutorPolicy.s4Title": "4. Pénzügyek és fizetések",
  "orgTutorPolicy.s4Intro": "Nem kell a számlázással vagy a szülői befizetések beszedésével foglalkoznod:",
  "orgTutorPolicy.s4Advance": "Az óráidért járó összes diák- vagy szülői befizetést előre beszedjük a Platformon keresztül, és közvetlenül a Szervezetednek utaljuk át.",
  "orgTutorPolicy.s4Confirmed": "Csak akkor tartasz meg egy órát, ha a rendszerben megerősített állapotú (vagyis az összegét már megterheltük).",
  "orgTutorPolicy.s4Contact": "A díjazásoddal, a kifizetések ütemezésével és más pénzügyi kérdésekkel közvetlenül a Szervezeted adminisztrátorához fordulj. Az MB Tutlio nem végez közvetlen pénzügyi tranzakciókat a Magántanárokkal.",
  "orgTutorPolicy.s5Title": "5. Diákadatok védelme (GDPR)",
  "orgTutorPolicy.s5Intro": "Magántanárként hozzáférsz a diákok személyes adataihoz, belső jegyzetekhez és tananyagokhoz. Vállalod, hogy:",
  "orgTutorPolicy.s5Use": "Az adatokat kizárólag az órák szervezésére és megtartására használod.",
  "orgTutorPolicy.s5NoCopy": "A diákok és szülők elérhetőségeit nem másolod, exportálod vagy terjeszted a Platformon kívül.",
  "orgTutorPolicy.s5Notes": "Megóvod a Szervezet belső nyilvántartásait (a diákok előrehaladásáról szóló jegyzeteket), amelyek csak számodra és a Szervezet adminisztrációja számára láthatók, a diákok és szülők számára nem.",
  "orgTutorPolicy.s5Termination": "A Szervezettel fennálló munkakapcsolatod megszűnésekor azonnal visszavonjuk a hozzáférésedet ezekhez az adatokhoz.",
  "orgTutorPolicy.s6Title": "6. Műszaki működés és felelősségkorlátozás",
  "orgTutorPolicy.s6Body": "Tilos a Platformot jogellenes célra használni, rosszindulatú linkeket terjeszteni a tananyagokban vagy más módon megzavarni a rendszert. Az MB Tutlio biztosítja a Platform működését és műszaki karbantartását, de nem vállal felelősséget az internetkapcsolatod, az eszközeid meghibásodása vagy a helytelen Google Calendar-beállítások miatt bekövetkező fennakadásokért.",
  "orgTutorPolicy.s7Title": "7. Támogatás és kapcsolattartás",
  "orgTutorPolicy.s7Org": "Az órarenddel, a díjazással, a diákok hozzárendelésével vagy a munkaszervezéssel kapcsolatos kérdésekben a Szervezeted adminisztrátorához fordulj.",
  "orgTutorPolicy.s7Tech": "A Platform műszaki hibáiról (nem működő naptárszinkronizálás, elmaradó értesítések) tájékoztasd a Szervezeted adminisztrátorát, aki felveszi a kapcsolatot a Tutlio műszaki ügyfélszolgálatával.",
  "register.orgPolicyConsent": "Platformunk használatával elfogadod a",
  "register.orgPolicyLink": "belső szabályzatot",
