  "quiz.offer.testimonial.solo.copy3": "„A nyilvános oldal és az egy linken elérhető foglalás gyorsabban segít dönteni az új diákoknak, nekem pedig nem kell ugyanazt az információt mindenkinek külön elküldenem.”",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Fizikatanár",
  "quiz.offer.testimonial.solo.copy4": "„A naptárban azonnal látom az órákat, a változásokat és a fizetési állapotokat. A napi adminisztráció sokkal rövidebb és átláthatóbb lett.”",
  "quiz.offer.testimonial.company.name1": "PRO KLASĖ",
  "quiz.offer.testimonial.company.role1": "Oktatási szervezet csapata",
  "quiz.offer.testimonial.company.copy1": "„Korábban külön üzenetekben érkeztek az óramódosítások, a magántanári megjegyzések és az óraszámok. Most az adminisztrációs csapat egyetlen órarendben látja a teljes képet.”",
  "quiz.offer.testimonial.company.name2": "Független oktatási központ",
  "quiz.offer.testimonial.company.role2": "Tulajdonos · 8 magántanár",
  "quiz.offer.testimonial.company.copy2": "„Korábban péntek esténként a naptárt hasonlítottam össze a magántanárok üzeneteivel a díjazás előkészítéséhez. A Tutlióval ennek az ellenőrzésnek a nagy része már kész.”",
  "quiz.offer.testimonial.company.name3": "Nyelvoktató stúdió",
  "quiz.offer.testimonial.company.role3": "Operatív vezető · 14 magántanár",
  "quiz.offer.testimonial.company.copy3": "„Ha áthelyezünk egy órát, a csapat rögtön ugyanazt a frissítést látja. Kevesebb az utólagos üzenet, a szülők pedig sokkal egyértelműbb válaszokat kapnak.”",
  "quiz.offer.testimonial.company.name4": "Vizsgafelkészítő akadémia",
  "quiz.offer.testimonial.company.role4": "Pénzügyi koordinátor · 22 magántanár",
  "quiz.offer.testimonial.company.copy4": "„A magántanári díjazásunk óratípusonként eltér, ezért korábban a hónapzárás sok kézi ellenőrzéssel járt. A Tutlio folyamata jóval nyugodtabbá tette ezt.”",
  "quiz.offer.testimonial.school.name1": "VšĮ “Laisvi vaikai”",
  "quiz.offer.testimonial.school.role1": "Iskolai adminisztrációs csapat",
  "quiz.offer.testimonial.school.copy1": "„A legegyértelműbb javulás az, hogy több ember megkérdezése vagy külön fájlok ellenőrzése nélkül látjuk a szerződések, aláírások és fizetések állapotát.”",
  "quiz.offer.testimonial.school.name2": "Független közösségi iskola",
  "quiz.offer.testimonial.school.role2": "Felvételi koordinátor · 86 tanuló",
  "quiz.offer.testimonial.school.copy2": "„A beiratkozási időszak korábban külön mappákban vezetett űrlapokat, szülői adatokat és aláírt szerződéseket jelentett. Most a csapat egyetlen helyről követheti az egyes családokat.”",
  "quiz.offer.testimonial.school.name3": "Délutáni oktatási központ",
  "quiz.offer.testimonial.school.role3": "Adminisztrátor · 120 tanuló",
  "quiz.offer.testimonial.school.copy3": "„A részletfizetési ütemezések sokkal nyugodtabbá tették a fizetések követését. Mielőtt megkeresek egy szülőt, látom, mi esedékes, és nem kell kézzel újra összeállítanom a listát.”",
  "quiz.offer.testimonial.school.name4": "Művészeti iskola",
  "quiz.offer.testimonial.school.role4": "Pénzügyi koordinátor · 9 képzés",
  "quiz.offer.testimonial.school.copy4": "„A könyvelési export most ugyanazokból a nyilvántartásokból készül, amelyeket a szerződésekhez és fizetésekhez használunk, így hónapzáráskor jóval kevesebbet kell javítanunk.”",
  "quiz.offer.savings.eyebrow": "Becsült időmegtakarítás",
  "quiz.offer.savings.subtitle": "Az ismétlődő adminisztráció becsült csökkenése, ha ezeket a folyamatokat a Tutlio összekapcsolja.",
  "quiz.offer.savings.totalLabel": "az ismétlődő adminisztráció lehetséges csökkenése",
