  "landing.custom.title": "Szoftver, amely az Ön munkamódszeréhez igazodik - nem fordítva",
  "landing.custom.sub": "Minden iskola és ügynökség kicsit másképp működik. Ha a szokásos folyamat nem illeszkedik, a Tutliót igazítjuk az Ön folyamatához - jellemzően hetek, nem negyedévek alatt. Néhány dolog, amit már megépítettünk ügyfeleinknek:",
  "landing.custom.ex1Title": "Éves szerződések elektronikus aláírással",
  "landing.custom.ex1Desc": "Egy magániskolának arra volt szüksége, hogy a szülők elektronikusan írják alá az éves szerződéseket, részletekben fizessenek, és minden befizetés megjelenjen egy könyvelésre kész exportban. Ma a teljes folyamat a Tutlión belül zajlik.",
