  "landing.custom.ex2Desc": "Egy ügynökség minden tanárt tantárgy és óratípus szerint fizet, a cég jutalékával kiegészítve. Leképeztük a szabályaikat, így a havi tanári kimutatások és a számlák automatikusan elkészülnek.",
  "landing.custom.ex3Title": "Egykattintásos ajánlatok a szülőknek",
  "landing.custom.ex3Desc": "Egy iskola e-mailben szeretett volna kiegészítő órákat ajánlani úgy, hogy a szülők egyetlen kattintással elfogadhassák - fiók és nyomtatás nélkül. Az elfogadás, a számlázás és az első órára szóló meghívó ma már magától fut.",
  "landing.custom.ex4Title": "Az Ön arculata a saját weboldalán",
  "landing.custom.ex4Desc": "Egy szervezet a saját logóját és színeit szerette volna, valamint a weboldalába ágyazott bejelentkezést, hogy a diákok és a szülők soha ne érezzék, hogy elhagyták az oldalt. A Tutlio ma az ő arculatukkal fut.",
  "landing.custom.note": "Ezek egyike sem külön kiadás. Minden testreszabás annak a terméknek a része lesz, amelyet a csapata már használ, az összes jövőbeli frissítéssel együtt.",
