  "compare.hub.subtitle": "Őszinte, pontról pontra haladó összehasonlítások azokkal az eszközökkel, amelyeket a magántanárok és a tanodák a leggyakrabban mérlegelnek. Ha egy versenytárs jobban illik hozzád, azt is megírjuk.",
