  "compare.oases.metaDesc": "Tutlio vs Oases Online korrepetáló központoknak és több telephelyes programoknak: aktív diákok szerinti árazás tanári licencek helyett, párosítás, felmérések, szerződések, nyelvek és egyedi funkciók.",
