  "compare.oases.intro2": "A Tutlio könnyebb, gyorsabb indulást ad a korrepetáló tanodáknak és ügynökségeknek: naptár és önálló foglalás, Stripe-fizetés és számlák, részletfizetéses szerződések, tanári díjazás, szülői fiókok, várólista, tábla és 36 felületi nyelv - tanáronkénti árral az aktív diák szerinti helyett, próbaidőszakkal és kérésre egyedi funkciókkal.",
